package org.brightstats.model;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
import org.brightstats.model.ElementType.Family;
import org.brightstats.model.TypedDiagram.*;
import org.brightstats.stats.*;
public final class DiagramSemChecks {
    static int checks;static void check(boolean value){checks++;if(!value)throw new AssertionError("Diagram SEM check "+checks);}
    static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid SEM diagram accepted");}catch(IllegalArgumentException expected){checks++;}}
    static Node node(String id,ElementType type,String label,String column){JsonObject properties=new JsonObject();if(column!=null)properties.addProperty("column",column);return new Node(id,type,label,100,100,properties);}
    static Link link(String id,ElementType type,String source,String target){return new Link(id,type,source,target,new JsonObject());}
    public static void main(String[] args)throws Exception{
        List<String> names=List.of("A1","A2","A3","B1","B2","B3");Random random=new Random(818);double[][] data=new double[400][6];for(var row:data){double a=random.nextGaussian(),b=.5*a+.7*random.nextGaussian(),e=random.nextGaussian();row[0]=a+.4*e;row[1]=.8*a+.4*random.nextGaussian();row[2]=1.2*a+.4*random.nextGaussian();row[3]=b+.4*(.3*e+Math.sqrt(.91)*random.nextGaussian());row[4]=.9*b+.4*random.nextGaussian();row[5]=1.1*b+.4*random.nextGaussian();}
        List<Node> nodes=new ArrayList<>(List.of(node("root",ElementType.ROOT,"Model",null),node("a",ElementType.CBSEM_LATENT_VARIABLE,"A",null),node("b",ElementType.CBSEM_LATENT_VARIABLE,"B",null)));List<Link> links=new ArrayList<>();for(int i=0;i<6;i++){nodes.add(node("v"+i,ElementType.CBSEM_STANDARD_MANIFEST_VARIABLE,"Display "+names.get(i),names.get(i)));links.add(link("loading"+i,ElementType.CBSEM_CONNECTION_BETWEEN_LV_AND_MV,i<3?"a":"b","v"+i));}links.add(link("structural",ElementType.CBSEM_CONNECTION_BETWEEN_LV_AND_LV,"a","b"));nodes.add(node("error_a",ElementType.CBSEM_ERROR_TERM,"eA1",null));nodes.add(node("error_b",ElementType.CBSEM_ERROR_TERM,"eB1",null));links.add(link("bind_a",ElementType.CBSEM_CONNECTION_BETWEEN_MV_AND_ERROR_TERM,"error_a","v0"));links.add(link("bind_b",ElementType.CBSEM_CONNECTION_BETWEEN_MV_AND_ERROR_TERM,"v3","error_b"));links.add(link("error_covariance",ElementType.CBSEM_CORRELATION_CONNECTION_BETWEEN_ERROR_TERM_AND_ERROR_TERM,"error_a","error_b"));var document=new Document(1,Family.CBSEM,"root",nodes,links,List.of());var compiled=DiagramSem.compile(document,names,data,false);check(compiled.prepared().model().variables().size()==8);check(Arrays.equals(compiled.prepared().columns(),new int[]{0,1,2,3,4,5}));check(compiled.prepared().factors().length==2);check(compiled.warnings().stream().filter(note->note.startsWith("Automatic fixed marker")).count()==2);var fit=CovarianceSem.fit(compiled.prepared().select(data),compiled.prepared().model(),CovarianceSem.Options.defaults());check(fit.converged());check(Math.abs(fit.directed()[1][0]-.5)<.15);
        var history=new TypedDiagramHistory(document);var renamed=document.with(document.node("a").named("Renamed A")).move(Set.of("v0","error_a"),50,-25);history.record(renamed);check(history.canUndo());check(history.undo().equals(document));check(history.redo().equals(renamed));history.undo();history.record(document.move(Set.of("a"),5,5));check(!history.canRedo());check(history.retainedBytes()>0);
        JsonObject equality=new JsonObject();equality.addProperty("equality","equal_loading");equality.addProperty("value",.9);equality.addProperty("lower",.1);equality.addProperty("upper",2);var constrained=document.with(new Link("loading1",ElementType.CBSEM_CONNECTION_BETWEEN_LV_AND_MV,"a","v1",equality)).with(new Link("loading2",ElementType.CBSEM_CONNECTION_BETWEEN_LV_AND_MV,"a","v2",equality));var restricted=DiagramSem.compile(constrained,names,data,false);var parameter=restricted.prepared().model().parameters().stream().filter(value->value.name().equals("equal_loading")).findFirst().orElseThrow();check(parameter.locations().size()==2&&parameter.lower()==.1&&parameter.upper()==2);check(DiagramSem.compile(document,names,data,true).prepared().model().parameters().stream().filter(value->value.locations().getFirst().kind()==SemModel.Kind.INTERCEPT).count()==6);
        reject(()->DiagramSem.compile(document.with(node("orphan",ElementType.CBSEM_ERROR_TERM,"Orphan",null)),names,data,false));reject(()->DiagramSem.compile(document.with(link("duplicate_error",ElementType.CBSEM_CONNECTION_BETWEEN_MV_AND_ERROR_TERM,"error_a","v1")),names,data,false));reject(()->DiagramSem.compile(document.with(link("duplicate_cov",ElementType.CBSEM_CORRELATION_CONNECTION_BETWEEN_MV_AND_MV,"v0","v3")),names,data,false));reject(()->DiagramSem.compile(document.with(node("duplicate_column",ElementType.CBSEM_STANDARD_MANIFEST_VARIABLE,"Duplicate","A1")),names,data,false));JsonObject mean=new JsonObject();mean.addProperty("free",true);var props=document.node("a").properties();props.add("mean",mean);reject(()->DiagramSem.compile(document.with(new Node("a",ElementType.CBSEM_LATENT_VARIABLE,"A",0,0,props)),names,data,false));
        Path output=Path.of(args[0]);Files.createDirectories(output);JsonObject evidence=new JsonObject();var gson=new GsonBuilder().serializeSpecialFloatingPointValues().create();evidence.add("diagram",document.json());evidence.add("observations",gson.toJsonTree(data));evidence.add("compiled",gson.toJsonTree(compiled));evidence.add("fit",gson.toJsonTree(fit));Files.writeString(output.resolve("sem-compiled.json"),gson.toJson(evidence));System.out.println("{\"checks\":"+checks+",\"ram_variables\":8}");
    }
}
